using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using TuneHire.Api.Data; using TuneHire.Api.Models; namespace TuneHire.Api.Controllers { [ApiController] [Route("api/[controller]")] public class MusiciansController : ControllerBase { private readonly AppDbContext _db; public MusiciansController(AppDbContext db) { _db = db; } [HttpGet] public async Task<IActionResult> Get([FromQuery] string genre, [FromQuery] string location) { var q = _db.Musicians.AsQueryable(); if (!string.IsNullOrEmpty(genre)) q = q.Where(m => m.Genre.Contains(genre)); if (!string.IsNullOrEmpty(location)) q = q.Where(m => m.Location.Contains(location)); var list = await q.ToListAsync(); return Ok(list); } [HttpGet("{id}")] public async Task<IActionResult> GetById(int id) => Ok(await _db.Musicians.FindAsync(id)); [HttpPost] public IActionResult Create(Musician m) { _db.Musicians.Add(m); _db.SaveChanges(); return CreatedAtAction(nameof(GetById), new { id = m.Id }, m); } } }